drop policy if exists parent_links_staff_write on public.parent_links;create policy parent_links_staff_write on public.parent_links for insert to authenticated with check(public.has_any_role(array['super_admin','mentor_manager']::public.app_role[]));
drop policy if exists parent_links_staff_update on public.parent_links;create policy parent_links_staff_update on public.parent_links for update to authenticated using(public.has_any_role(array['super_admin','mentor_manager']::public.app_role[])) with check(public.has_any_role(array['super_admin','mentor_manager']::public.app_role[]));
create or replace function private.consent_parent_link(p_link_id uuid) returns public.parent_links language plpgsql security definer set search_path=public,pg_temp as $$ declare v_link public.parent_links%rowtype; begin if auth.uid() is null then raise exception 'authentication_required'; end if; update public.parent_links set consented_at=coalesce(consented_at,now()),is_active=true where id=p_link_id and youth_user_id=auth.uid() returning * into v_link; if not found then raise exception 'parent_link_not_found'; end if; return v_link; end; $$;
revoke all on function private.consent_parent_link(uuid) from public,anon,authenticated;drop function if exists public.consent_parent_link(uuid);create or replace function public.consent_parent_link(p_link_id uuid) returns public.parent_links language sql security invoker set search_path=public,pg_temp as $$ select * from private.consent_parent_link(p_link_id); $$;revoke all on function public.consent_parent_link(uuid) from public,anon;grant execute on function public.consent_parent_link(uuid) to authenticated;